import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it } from 'vitest'
import App from './App'

describe('Memory OS app', () => {
  beforeEach(() => {
    window.location.hash = '#/home'
  })

  it('opens the Orbit home inside the Memory OS navigation shell', async () => {
    render(<App />)

    expect(await screen.findByRole('heading', { name: '지금 당신은 이렇게 생겼습니다' })).toBeInTheDocument()
    expect(screen.getByRole('navigation', { name: '주요 화면' })).toBeInTheDocument()
    expect(screen.getByRole('link', { name: /Changes/ })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: '요즘 나 뭐 하고 있어?' })).toHaveAttribute('aria-pressed', 'true')
  })

  it('routes every sidebar menu to a working screen', async () => {
    const user = userEvent.setup()
    render(<App />)

    await user.click(await screen.findByRole('link', { name: /Changes/ }))
    expect(await screen.findByRole('heading', { name: /이번 주, AI가 당신에 대해/ })).toBeInTheDocument()
    await user.click(screen.getByRole('link', { name: /Memory/ }))
    expect(await screen.findByRole('heading', { name: /어떤 것이 식어가고 있는가/ })).toBeInTheDocument()
    await user.click(screen.getByRole('link', { name: /Chat/ }))
    expect(await screen.findByRole('heading', { name: '대화하면서, 기억을 바로잡으세요' })).toBeInTheDocument()
    await user.click(screen.getByRole('link', { name: /Access/ }))
    expect(await screen.findByRole('heading', { name: /어떤 AI가.*무엇을 기억/ })).toBeInTheDocument()
    await user.click(screen.getByRole('link', { name: /Settings/ }))
    expect(await screen.findByRole('heading', { name: '기억의 원본은 당신에게 있습니다' })).toBeInTheDocument()
  })

  it('answers a different Orbit question when its chip is selected', async () => {
    const user = userEvent.setup()
    render(<App />)

    await user.click(await screen.findByRole('button', { name: '작년의 나와 뭐가 달라?' }))

    expect(screen.getByText(/스택 고착이 사라졌고/)).toBeInTheDocument()
    expect(screen.getByRole('button', { name: '작년의 나와 뭐가 달라?' })).toHaveAttribute('aria-pressed', 'true')
  })

  it('reviews and accepts a proposed memory change', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/changes'
    render(<App />)

    expect(await screen.findByRole('heading', { name: /이번 주, AI가 당신에 대해/ })).toBeInTheDocument()
    await user.click(screen.getByRole('button', { name: '변경 내용 보기' }))
    expect(screen.getByRole('dialog', { name: '이해 업데이트 제안' })).toBeInTheDocument()
    await user.click(screen.getByRole('button', { name: '이 이해를 승인' }))
    expect(await screen.findByText(/업데이트했습니다/)).toBeInTheDocument()
  })

  it('reveals secondary changes only when requested', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/changes'
    render(<App />)

    expect(await screen.findByRole('heading', { name: 'Flutter를 더 이상 선호하지 않을 수 있습니다.' })).toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: '이 두 기억은 같은 이야기로 보입니다.' })).not.toBeInTheDocument()

    await user.click(screen.getByRole('button', { name: '나머지 3개 보기' }))
    expect(screen.getByRole('heading', { name: '이 두 기억은 같은 이야기로 보입니다.' })).toBeInTheDocument()
  })

  it('pins a memory from the half-life lens', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/memory/half-life'
    render(<App />)

    expect(await screen.findByRole('heading', { name: /어떤 것이 식어가고 있는가/ })).toBeInTheDocument()
    const pin = screen.getByRole('button', { name: '창업은 B2C 위주로 하고 싶음 고정' })
    await user.click(pin)
    expect(pin).toHaveAttribute('aria-pressed', 'true')
  })

  it('opens the cleanup flow from the half-life lens', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/memory/half-life'
    render(<App />)

    await user.click(await screen.findByRole('button', { name: '하나씩 보기' }))
    expect(await screen.findByRole('dialog', { name: '기억 정리' })).toBeInTheDocument()
  })

  it('resolves a constellation tension as a conditional memory', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/memory/constellation'
    render(<App />)

    expect(await screen.findByRole('heading', { name: /네 개의 덩어리/ })).toBeInTheDocument()
    await user.click(screen.getByRole('button', { name: '조건부 기억으로 분리' }))
    expect(await screen.findByText('조건부 기억으로 분리했습니다.')).toBeInTheDocument()
  })

  it('opens sentence evidence in the manual lens', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/memory/manual'
    render(<App />)

    expect(await screen.findByRole('heading', { name: '제가 지금 알고 있는 당신' })).toBeInTheDocument()
    await user.click(screen.getByRole('button', { name: '도구와 코드 근거 보기' }))
    expect(screen.getByText('Swift 프로젝트 2개')).toBeInTheDocument()
  })

  it('applies a detected chat correction to every conversation', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/chat'
    render(<App />)

    const input = await screen.findByPlaceholderText('메시지를 입력하세요')
    await user.type(input, '나 요즘 Flutter 잘 안 쓰는데')
    await user.click(screen.getByRole('button', { name: '메시지 보내기' }))
    expect(screen.getByText('기억 수정 감지')).toBeInTheDocument()
    await user.click(screen.getByRole('button', { name: '모든 대화에 반영' }))
    expect(await screen.findByText('모든 대화에 반영했습니다.')).toBeInTheDocument()
  })

  it('changes one AI access rule and restores the demo from settings', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/access'
    render(<App />)

    const toggle = await screen.findByRole('switch', { name: '회사 AI 개인 기억' })
    expect(toggle).toHaveAttribute('aria-checked', 'false')
    await user.click(toggle)
    expect(toggle).toHaveAttribute('aria-checked', 'true')

    await user.click(screen.getByRole('link', { name: /Settings/ }))
    await user.click(await screen.findByRole('button', { name: '데모 초기화' }))
    expect(await screen.findByText('데모 데이터를 초기 상태로 되돌렸습니다.')).toBeInTheDocument()
  })

  it('filters the raw memory list to items that need review', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/settings'
    render(<App />)

    expect(await screen.findByRole('button', { name: '원본 기억 목록 열기' })).toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: '전체 기억 612개' })).not.toBeInTheDocument()
    await user.click(screen.getByRole('button', { name: '원본 기억 목록 열기' }))
    expect(screen.getByRole('heading', { name: '전체 기억 612개' })).toBeInTheDocument()
    await user.click(screen.getByRole('button', { name: '검토 중' }))

    expect(screen.getByText('창업은 B2C 위주로 하고 싶음')).toBeInTheDocument()
    expect(screen.queryByText('AI 코딩 도구를 상시 사용함')).not.toBeInTheDocument()
  })

  it('opens archived memories from the settings shortcut', async () => {
    const user = userEvent.setup()
    window.location.hash = '#/settings'
    render(<App />)

    await user.click(await screen.findByRole('button', { name: '열기' }))
    expect(screen.getByRole('heading', { name: '전체 기억 612개' })).toBeInTheDocument()
    expect(screen.getByText('커피는 디카페인으로 마심')).toBeInTheDocument()
    expect(screen.getByRole('button', { name: '보관됨' })).toHaveAttribute('aria-pressed', 'true')
  })
})

